using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.IO;using System.Text.Json;using Sdt.Core;using Sdt.Core.Battle;
class TargetTests
{
 sealed class Host:BattleHost{public int Hp{get;set;}=30;public int MaxHp=>60;public int Atk=>4;public int SpellPower=>2;public string MyClass=>null;public string CharacterId=>"wu";public IReadOnlyList<OwnedCard> OwnedCards{get;set;}=Array.Empty<OwnedCard>();public void Log(string s,string k=null){}public void Heal(int n){Hp=Math.Min(MaxHp,Hp+n);}public void OnBattleEnd(BattleResult r){}}
 static int count;static void Check(bool ok,string why){if(!ok)throw new Exception(why);count++;}
 static object Field(BattleSession b,string n)=>typeof(BattleSession).GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(b);
 static BattleSession Make(params CardDef[] cards){var b=new BattleSession();b.Start(new BattleStartContext{host=new Host{OwnedCards=cards.Select((c,i)=>new OwnedCard{uid="o"+i,card=c}).ToArray()},rng=new Rng(123),enemies=new[]{new EnemyInput{id="a",name="甲",hp=100,atk=2},new EnemyInput{id="b",name="乙",hp=100,atk=3},new EnemyInput{id="c",name="丙",hp=100,atk=6}}});return b;}
 static CardDef Card(string id)=>CardLibrary.FindById(id);
 static CommandResult Pick(BattleSession b,int index){var p=b.Snapshot.PendingTarget;return b.SelectRuleTarget(index,p.BattleToken,p.SelectionId);}
 static void Main(){CardLibrary.Init(()=>CardDatabase.All);
 var im=Make(Card("cmtn233trmeg"));Check(im.PlayCard("o0",0,false).Ok,"immortal first");Check(im.Snapshot.Hand.Contains("o0"),"same uid retained");Check(!((List<string>)Field(im,"played")).Contains("o0"),"retained not spent");Check(im.PlayCard("o0",0,false).Ok,"immortal twice");Check(im.Snapshot.Foes[0].hp==90&&im.Snapshot.Energy==0,"twice damage and cost");im.Retract();
 var fu=Make(Card("tt3sp-silverthorn"),Card("cmtn233trmeg"),Card("starter-attack"));fu.PlayCard("o0",0,false);Check(fu.Snapshot.Infusing!=null,"fuel choice");Check(!fu.SelectInfusion("o1").Ok&&!fu.Snapshot.Infusing.Picked.Any(),"blocked fuel");Check(fu.SelectInfusion("o2").Ok&&fu.Snapshot.Infusing.Picked.Contains("o2"),"legal fuel");fu.SelectInfusion("o2");Check(!fu.Snapshot.Infusing.Picked.Any(),"uid toggle");fu.Retract();
 var d=Make(Card("tt7-bloodpoison"));Check(d.PlayCard("o0",0,false).Ok,"dart main");Check(d.Snapshot.PendingTarget?.Kind=="rulePick","dart independent target");Check(d.Snapshot.Foes[0].hp==95&&d.Snapshot.Foes[0].status["bleed"]==1&&d.Snapshot.Foes[0].status["poison"]==0,"first segment only");var old=d.Snapshot.PendingTarget;Check(!d.SelectRuleTarget(1,"wrong",old.SelectionId).Ok,"token invalid");Check(!d.SelectRuleTarget(1,old.BattleToken,old.SelectionId+1).Ok,"selection invalid");Check(!Pick(d,-1).Ok&&d.Snapshot.PendingTarget!=null,"invalid target retry");Check(Pick(d,1).Ok,"second select");Check(d.Snapshot.Foes[1].hp==95&&d.Snapshot.Foes[1].status["poison"]==1&&d.Snapshot.Foes[0].status["poison"]==0,"split segment binding");Check(d.Snapshot.Energy==0,"second segment no payment");Check(!d.SelectRuleTarget(2,old.BattleToken,old.SelectionId).Ok,"single use");d.Retract();
 d=Make(Card("tt7-bloodpoison"));d.PlayCard("o0",0,false);Check(Pick(d,0).Ok,"repeated same target");Check(d.Snapshot.Foes[0].hp==89,"second hit sees bleed");d.Retract();
 d=Make(Card("tt7-bloodpoison"));d.PlayCard("o0",0,false);old=d.Snapshot.PendingTarget;d.CancelPendingTarget();Check(!d.SelectRuleTarget(1,old.BattleToken,old.SelectionId).Ok,"cancel invalidates");Check(d.EndTurn().Ok,"cancel does not block turn");d.Retract();
 d=Make(Card("tt7-bloodpoison"));d.PlayCard("o0",0,false);old=d.Snapshot.PendingTarget;Check(d.EndTurn().Ok&&d.Snapshot.PendingTarget==null,"end turn drops second");Check(!d.SelectRuleTarget(1,old.BattleToken,old.SelectionId).Ok,"turn invalidates");d.Retract();
 var p=Make(Card("tt7-provoke"));Check(!p.PlayCard("o0",1,false).Ok&&p.Snapshot.Energy==2,"first fighter no payment");Check(p.Snapshot.PendingTarget.ExcludedTargetIndex==1,"first fighter recorded");Check(!p.PlayCard("o0",1,false).Ok&&p.Snapshot.Energy==2,"same fighter rejected");Check(p.PlayCard("o0",2,false).Ok,"second fighter");Check(p.Snapshot.Foes[0].hp==100&&p.Snapshot.Foes[1].hp==94&&p.Snapshot.Foes[2].hp==97,"user order pair damage");Check(p.Snapshot.Energy==1,"pair pays once");p.Retract();
 p=Make(Card("tt7-provoke"));var foes=(List<BattleFoe>)Field(p,"foes");foes[2].hp=1;p.PlayCard("o0",1,false);p.PlayCard("o0",2,false);Check(p.Snapshot.Foes[2].Dead&&p.Snapshot.Foes[1].hp==100,"dead defender cannot retaliate");p.Retract();
 p=Make(Card("tt7-provoke"));p.PlayCard("o0",1,false);foes=(List<BattleFoe>)Field(p,"foes");foes[1].dead=true;p.PlayCard("o0",2,false);Check(p.Snapshot.PendingTarget.ExcludedTargetIndex==2&&p.Snapshot.Energy==2,"dead first reselects");p.Retract();
 d=Make(Card("tt7-bloodpoison"));d.PlayCard("o0",0,false);foes=(List<BattleFoe>)Field(d,"foes");foes[1].dead=true;Check(!Pick(d,1).Ok&&d.Snapshot.PendingTarget!=null,"dead second stays pending");Check(Pick(d,2).Ok,"dead target retry living");d.Retract();

 p=Make(Card("tt7-provoke"));foes=(List<BattleFoe>)Field(p,"foes");foes[0].dead=true;foes[1].dead=true;Check(!p.PlayCard("o0",2,false).Ok&&p.Snapshot.PendingTarget==null&&p.Snapshot.Energy==2,"one enemy rejects before selection");p.Retract();
 p=Make(Card("tt7-provoke"));foes=(List<BattleFoe>)Field(p,"foes");foes[1].status.atkUp=2;foes[2].status.bleed=2;p.PlayCard("o0",1,false);p.PlayCard("o0",2,false);Check(p.Snapshot.Foes[2].hp==93,"fighter uses attacker buff and target bleed");p.Retract();
 p=Make(Card("tt7-provoke"));p.PlayCard("o0",1,false);p.CancelPendingTarget();p.PlayCard("o0",2,false);Check(p.Snapshot.PendingTarget.ExcludedTargetIndex==2&&p.Snapshot.Energy==2,"cancel clears first fighter");p.Retract();
 d=Make(Card("tt7-bloodpoison"));d.PlayCard("o0",0,false);old=d.Snapshot.PendingTarget;d.Start(new BattleStartContext{host=new Host{OwnedCards=new[]{new OwnedCard{uid="o0",card=Card("tt7-bloodpoison")}}},enemies=new[]{new EnemyInput{id="x",name="新",hp=100,atk=1}}});Check(!d.SelectRuleTarget(0,old.BattleToken,old.SelectionId).Ok,"cross battle target invalidates");d.Retract();
 var retain=Card("cmtn233trmeg").Clone();retain.id="generic-retain-draw";retain.rules=RuleValue.Obj("battle",RuleValue.Obj("keepInHand",true,"target",RuleValue.Obj("side","self","area",false)),"triggers",RuleValue.Obj("onPlay",RuleValue.Arr(RuleValue.Obj("op","draw","amount",GameRules.BattleHandMax))));
 im=Make(new[]{retain}.Concat(Enumerable.Repeat(Card("starter-attack"),GameRules.BattleHandMax)).ToArray());((List<string>)Field(im,"hand")).Clear();((List<string>)Field(im,"hand")).Add("o0");((List<string>)Field(im,"drawPile")).Clear();((List<string>)Field(im,"drawPile")).AddRange(Enumerable.Range(1,GameRules.BattleHandMax).Select(i=>"o"+i));typeof(BattleSession).GetField("mode",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(im,"boss");Check(im.PlayCard("o0",-1,false).Ok,"generic retain draw cast");Check(im.Snapshot.Hand.Count==GameRules.BattleHandMax&&!im.Snapshot.Hand.Contains("o0")&&im.Snapshot.Discard.Contains("o0"),"retain draw uses freed slot and full hand fallback");im.Retract();

 var infusedPair=Card("tt7-provoke").Clone();infusedPair.infuse=1;p=Make(infusedPair,Card("starter-attack"));p.PlayCard("o0",1,false);p.SelectInfusion("o1");Check(!p.ConfirmInfusion(1).Ok&&p.Snapshot.PendingTarget.ExcludedTargetIndex==1,"infusion first pair selection");Check(p.Snapshot.Hand.Contains("o1")&&p.Snapshot.Energy==2,"target before atomic fuel payment");Check(p.PlayCard("o0",2,false).Ok&&p.Snapshot.ConsumedPile.Contains("o1")&&p.Snapshot.Foes[2].hp==97,"selected fuel survives pair selection");p.Retract();
 var self=infusedPair.Clone();self.rules=RuleValue.Obj("battle",RuleValue.Obj("target",RuleValue.Obj("side","self","area",false)),"triggers",RuleValue.Obj("onPlay",RuleValue.Arr(RuleValue.Obj("op","armor","amount",2))));p=Make(self,Card("starter-attack"));p.PlayCard("o0",-2,false);p.SelectInfusion("o1");Check(!p.ConfirmInfusion(-2).Ok&&p.Snapshot.PendingTarget!=null&&p.Snapshot.Energy==2,"self target must be chosen after infusion");Check(p.PlayCard("o0",-1,false).Ok&&p.Snapshot.Pdef.Armor==2&&p.Snapshot.ConsumedPile.Contains("o1"),"self choice preserves infusion");p.Retract();
 var mutable=Card("starter-attack").Clone();p=Make(infusedPair,mutable);p.PlayCard("o0",1,false);p.SelectInfusion("o1");mutable.rules=RuleValue.Obj("battle",RuleValue.Obj("fuelAllowed",false));Check(!p.ConfirmInfusion(1).Ok&&p.Snapshot.Energy==2&&p.Snapshot.Hand.Contains("o1"),"fuel revalidated atomically after transform");p.Retract();
 File.WriteAllText("target-tests-results.json",JsonSerializer.Serialize(new{passed=count,failed=0},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("PASS "+count);
 }
}

